//! FreeANDIY branding: the accent and flat print shape on upstream's themes, the UI font, the
//! wordmark and the upstream attribution shown in About.
//!
//! A video editor is judged against neutral greys, so the three themes keep upstream's panel
//! colours; FreeANDIY changes the accent (stamp rose), corners and shadows.

use std::sync::Arc;

use egui::{Color32, Context, FontData, FontDefinitions, FontFamily, Id, TextureHandle, TextureOptions, Ui, Visuals};

use crate::theme::{ThemeKind, Tokens};

pub const APP_NAME: &str = "{{this.name}}";
pub const OWNER: &str = "{{brand.owner}}";
pub const UPSTREAM_NAME: &str = "{{this.upstream_name}}";

const PAPER: Color32 = Color32::from_rgb({{rgb.paper}});
const ROSE: Color32 = Color32::from_rgb({{rgb.rose}});
const PINK: Color32 = Color32::from_rgb({{rgb.pink}});

/// FreeANDIY's accent on upstream's tokens.
pub fn tokens(t: Tokens) -> Tokens {
    let light = t.kind == ThemeKind::Light;
    Tokens { accent: ROSE, accent_hover: if light { Color32::from_rgb(0xA8, 0x33, 0x5C) } else { PINK }, focus: if light { ROSE } else { PINK }, ..t }
}

/// Flat print look for egui's own surfaces: nearly square windows and menus, no soft shadows.
pub fn visuals(v: &mut Visuals) {
    v.window_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.menu_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.popup_shadow = egui::epaint::Shadow::NONE;
    v.window_shadow = egui::epaint::Shadow::NONE;
}

/// The interface font: IBM Plex Sans (SIL Open Font License 1.1; licence in
/// freeandiy/assets/fonts/) first, upstream's Inter right after for what Plex lacks. Desktop only:
/// the web build keeps its fonts, so the wasm does not grow.
pub fn ui_fonts(fonts: &mut FontDefinitions) {
    #[cfg(not(target_arch = "wasm32"))]
    {
        let faces: [(FontFamily, &str, &'static [u8]); 3] = [
            (FontFamily::Proportional, "plex", include_bytes!("../../../freeandiy/assets/fonts/IBMPlexSans-Regular.ttf")),
            (FontFamily::Name("medium".into()), "plex-medium", include_bytes!("../../../freeandiy/assets/fonts/IBMPlexSans-Medium.ttf")),
            (FontFamily::Name("semibold".into()), "plex-semibold", include_bytes!("../../../freeandiy/assets/fonts/IBMPlexSans-SemiBold.ttf")),
        ];
        for (family, key, bytes) in faces {
            fonts.font_data.insert(key.to_string(), Arc::new(FontData::from_static(bytes)));
            fonts.families.entry(family).or_default().insert(0, key.to_string());
        }
    }
    #[cfg(target_arch = "wasm32")]
    let _ = fonts;
}

const LOGOTYPE_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-logotype-left-hor.png");
const SEAL_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-seal-rose.png");

/// The FreeANDIY logotype (black ink), in paper on dark themes.
pub fn wordmark_image(dark: bool) -> Option<egui::ColorImage> {
    let mut img = image::load_from_memory_with_format(LOGOTYPE_PNG, image::ImageFormat::Png).ok()?.to_rgba8();
    if dark {
        for p in img.pixels_mut() {
            p.0 = [PAPER.r(), PAPER.g(), PAPER.b(), p.0[3]];
        }
    }
    Some(egui::ColorImage::from_rgba_unmultiplied([img.width() as usize, img.height() as usize], img.as_raw()))
}

fn seal(ctx: &Context) -> Option<TextureHandle> {
    let id = Id::new("freeandiy-seal");
    if let Some(tex) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return Some(tex);
    }
    let img = image::load_from_memory_with_format(SEAL_PNG, image::ImageFormat::Png).ok()?.to_rgba8();
    let image = egui::ColorImage::from_rgba_unmultiplied([img.width() as usize, img.height() as usize], img.as_raw());
    let options = TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..TextureOptions::LINEAR };
    let tex = ctx.load_texture("freeandiy-seal", image, options);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

/// English, like upstream's About credits line.
const ATTRIBUTION: &str = "{app} is based on the open-source project {upstream} (© ArtCraft Team and contributors, MIT/Apache-2.0). FreeANDIY is not affiliated with the ArtCraft team.";

/// The About tab's attribution: the Free Andy Agency seal and the upstream credit (MIT/Apache-2.0
/// require keeping the notices; the ArtCraft brand terms allow naming the origin in plain text).
pub fn about_attribution(ui: &mut Ui, t: &Tokens) {
    ui.horizontal(|ui| {
        if let Some(tex) = seal(ui.ctx()) {
            ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(48.0, 48.0)));
        }
        ui.vertical(|ui| {
            let text = ATTRIBUTION.replace("{app}", APP_NAME).replace("{upstream}", UPSTREAM_NAME);
            ui.label(egui::RichText::new(text).small().color(t.text_dim));
            ui.label(egui::RichText::new(format!("© {OWNER}")).small().color(t.text_dim));
        });
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_brand_images_decode() {
        assert!(seal(&Context::default()).is_some());
        assert!(wordmark_image(true).is_some() && wordmark_image(false).is_some());
    }

    #[test]
    fn every_theme_takes_the_rose_accent() {
        for kind in [ThemeKind::Dark, ThemeKind::Medium, ThemeKind::Light] {
            assert_eq!(Tokens::for_kind(kind).accent, ROSE);
        }
    }
}
